create table tickets (amount numeric(12,2) not null, status smallint not null check ((status between 0 and 3)), ticket_date date not null, ticket_time time(0) not null, created_at timestamp(6) not null, customer_id uuid not null, id uuid not null, merchant_id uuid not null, fingerprint_hash varchar(255) not null, raw_ocr_text TEXT, rejection_reason varchar(255), ticket_number varchar(255) not null, primary key (id));
create table loyalties (points_balance integer not null, created_at timestamp(6) not null, updated_at timestamp(6) not null, version bigint not null, customer_id uuid not null, id uuid not null, merchant_id uuid not null, primary key (id), constraint uk_loyalty_customer_merchant unique (customer_id, merchant_id));
